        maxCols[i] = (grid[i] == null) ? 0 : grid[i].length;
    }
    boolean[][] visited = new boolean[rowCount][];
    for (int i = 0; i < rowCount; i++) {
        visited[i] = new boolean[maxCols[i]];
    }

    int deposits = 0;
    int[] dRow = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dCol = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rowCount; r++) {
        if (grid[r] == null) continue;
        for (int c = 0; c < grid[r].length; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                // BFS stack
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0];
                    int cc = pos[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = cr + dRow[k];
                        int nc = cc + dCol[k];
                        if (nr < 0 || nr >= rowCount) continue;
                        if (grid[nr] == null) continue;
                        if (nc < 0 || nc >= grid[nr].length) continue;
                        if (!visited[nr][nc] && grid[nr][nc] == '@') {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

