public static int countDoubles(int[] numbers) {
    // Handle null or empty input gracefully
    if (numbers == null || numbers.length == 0) {
        return 0;
    }

    // Use a HashSet to store all numbers for fast lookup
    java.util.Set<Integer> valueSet = new java.util.HashSet<>();
    for (int num : numbers) {
        valueSet.add(num);
    }

    int doubleCount = 0;

    // For each number, check if it's twice another number in the list
    for (int num : numbers) {
        // Only consider even numbers to avoid unnecessary checks
        if ((num & 1) == 0) {
            int half = num / 2;
            if (valueSet.contains(half)) {
                doubleCount++;
            }
        }
    }

    return doubleCount;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic input validation
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    if (start.length != 1 || end.length != 1) {
        return "cannot be travelled";
    }
    int s = start[0];
    int t = end[0];
    if (s < 0 || s >= n || t < 0 || t >= n) {
        return "cannot be travelled";
    }
    // Build adjacency list
    @SuppressWarnings("unchecked")
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] edge : paths) {
        if (edge == null || edge.length < 2) continue;
        int u = edge[0];
        int v = edge[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            // ignore invalid edges
            continue;
        }
        adj[u].add(v);
        adj[v].add(u);
    }
    // BFS to find connectivity
    boolean[] visited = new boolean[n];
    java.util.ArrayDeque<Integer> queue = new java.util.ArrayDeque<>();
    queue.add(s);
    visited[s] = true;
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        if (cur == t) {
            return "can be travelled";
        }
        for (int nei : adj[cur]) {
            if (!visited[nei]) {
                visited[nei] = true;
                queue.add(nei);
            }
        }
    }
    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        throw new IllegalArgumentException("Input date string cannot be null");
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Expected format \"MM dd yyyy\"");
    }
    int month, day, year;
    try {
        month = Integer.parseInt(parts[0]);
        day   = Integer.parseInt(parts[1]);
        year  = Integer.parseInt(parts[2]);
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Month, day, and year must be numeric");
    }

    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Month must be between 01 and 12");
    }

    // Create calendar and validate the date
    java.util.GregorianCalendar cal = new java.util.GregorianCalendar(year, month - 1, day);
    // GregorianCalendar will roll over if the supplied day is invalid; adjust check below
    if (cal.get(java.util.Calendar.MONTH) != month - 1 ||
        cal.get(java.util.Calendar.DAY_OF_MONTH) != day ||
        cal.get(java.util.Calendar.YEAR) != year) {
        throw new IllegalArgumentException("Invalid date");
    }

    String monthName = new java.text.DateFormatSymbols().getMonths()[month - 1];
    String weekDayName = new java.text.DateFormatSymbols().getWeekdays()[cal.get(java.util.Calendar.DAY_OF_WEEK)];

    return String.format("%s %d, %d is a %s", monthName, day, year, weekDayName);
}

public int[] twoSum(int[] nums, int target) {
    // Validate input: at least two elements are required
    if (nums == null || nums.length < 2) {
        throw new IllegalArgumentException("Input array must contain at least two numbers.");
    }

    // Map to store number -> its index
    java.util.Map<Integer, Integer> indexMap = new java.util.HashMap<>();

    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];

        // Check if the complement has already been seen
        if (indexMap.containsKey(complement)) {
            return new int[] { indexMap.get(complement), i };
        }

        // Store the current number and its index
        indexMap.put(nums[i], i);
    }

    // If no solution is found, throw an exception
    throw new IllegalStateException("No two-sum solution exists for the given input.");
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        // Determine which side is sorted
        if (nums[left] <= nums[mid]) { // left half is sorted
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else { // right half is sorted
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

