public int minCostClimbingStairs(int[] cost) {
    // Handle null or empty input: no steps, so no cost.
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    // If there is only one step, we can start from step 1 (the top) with zero cost.
    if (n == 1) {
        return 0;
    }
    // For two steps, the min cost is simply the cheaper of starting at step 0 or step 1.
    if (n == 2) {
        return Math.min(cost[0], cost[1]);
    }

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    // The top is just beyond the last index, reachable from the last two steps.
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int uniqueMorseRepresentations(String[] words) {
    // Standard Morse code representations for a-z
    String[] morse = {
        ".-", "-...", "-.-.", "-..", ".", "..-.", "--.", "....", "..", ".---",
        "-.-", ".-..", "--", "-.", "---", ".--.", "--.-", ".-.", "...", "-",
        "..-", "...-", ".--", "-..-", "-.--", "--.."
    };

    if (words == null) {
        return 0;
    }

    java.util.Set<String> unique = new java.util.HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue; // skip null words
        }
        StringBuilder transformed = new StringBuilder();
        for (char ch : word.toCharArray()) {
            if (ch >= 'a' && ch <= 'z') {
                transformed.append(morse[ch - 'a']);
            } else if (ch >= 'A' && ch <= 'Z') {
                transformed.append(morse[ch - 'A']);
            } else {
                // Ignore characters that are not alphabetic
                continue;
            }
        }
        unique.add(transformed.toString());
    }
    return unique.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null) {
        return false;
    }
    int n = s.length();
    if (k < 0) {
        return false;
    }
    if (k == 0) {
        // Only empty string exists
        return true;
    }
    if (k > n) {
        return false;
    }
    long total = 1L << k; // number of possible codes
    long possibleSubstrings = (long)n - k + 1;
    if (total > possibleSubstrings) {
        return false; // Not enough substrings to cover all codes
    }
    if (k <= 20) { // safe to use array
        int sz = (int)total;
        boolean[] seen = new boolean[sz];
        int mask = (1 << k) - 1;
        int value = 0;
        for (int i = 0; i < n; i++) {
            value = ((value << 1) & mask) | (s.charAt(i) - '0');
            if (i >= k - 1) {
                seen[value] = true;
            }
        }
        for (boolean b : seen) {
            if (!b) {
                return false;
            }
        }
        return true;
    } else {
        long mask = total - 1;
        long value = 0L;
        java.util.HashSet<Long> seen = new java.util.HashSet<>((int)Math.min(total, 1_000_000));
        for (int i = 0; i < n; i++) {
            value = ((value << 1) & mask) | (s.charAt(i) - '0');
            if (i >= k - 1) {
                seen.add(value);
            }
        }
        return seen.size() == total;
    }
}

