public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int balance = 0; // number of unmatched '('
    int insertions = 0; // number of insertions needed for unmatched ')'
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            balance--;
            if (balance < 0) {
                // we have an unmatched ')', need to insert a '(' before it
                insertions++;
                balance = 0;
            }
        } else {
            // invalid character, skip or could throw exception; here we skip
            continue;
        }
    }
    // any remaining unmatched '(' need matching ')'
    insertions += balance;
    return insertions;
}

