public int maxAbsoluteSum(int[] nums) {
    try {
        if (nums == null || nums.length == 0) {
            return 0;
        }

        long maxEndingHere = nums[0];
        long maxSoFar = nums[0];
        long minEndingHere = nums[0];
        long minSoFar = nums[0];

        for (int i = 1; i < nums.length; i++) {
            int val = nums[i];

            // For maximum subarray sum
            maxEndingHere = Math.max(val, maxEndingHere + val);
            maxSoFar = Math.max(maxSoFar, maxEndingHere);

            // For minimum subarray sum
            minEndingHere = Math.min(val, minEndingHere + val);
            minSoFar = Math.min(minSoFar, minEndingHere);
        }

        long absMax = Math.abs(maxSoFar);
        long absMin = Math.abs(minSoFar);
        return (int) Math.max(absMax, absMin);
    } catch (Exception e) {
        throw new RuntimeException("Error computing maximum absolute subarray sum", e);
    }
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0; // No positive Fibonacci sum possible for non‑positive k
    }
    // Generate Fibonacci numbers up to k
    List<Integer> fib = new ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int size = fib.size();
        int next = fib.get(size - 1) + fib.get(size - 2);
        if (next > k) {
            break;
        }
        fib.add(next);
    }

    int remaining = k;
    int count = 0;
    // Greedy subtraction from the largest Fibonacci number
    for (int i = fib.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fib.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    int sqrt = (int)Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    int count = 0;
    for (int v : small) {
        count++;
        if (count == k) return v;
    }
    for (int i = large.size() - 1; i >= 0; i--) {
        count++;
        if (count == k) return large.get(i);
    }
    return -1;
}

public String makeGood(String s) {
    try {
        if (s == null) {
            return null;
        }
        StringBuilder stack = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            int len = stack.length();
            if (len > 0) {
                char top = stack.charAt(len - 1);
                if (Character.toLowerCase(c) == Character.toLowerCase(top)
                        && Character.isUpperCase(c) != Character.isUpperCase(top)) {
                    stack.deleteCharAt(len - 1);
                    continue;
                }
            }
            stack.append(c);
        }
        return stack.toString();
    } catch (Exception e) {
        // In case of unexpected runtime issues, return an empty string
        return "";
    }
}

