public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long pos = 1; // current digit position (1, 10, 100, ...)
    while (pos <= n) {
        long divisor = pos * 10;
        long higher = n / divisor;
        long current = (n / pos) % 10;
        long lower = n % pos;

        if (current == 0) {
            count += higher * pos;
        } else if (current == 1) {
            count += higher * pos + lower + 1;
        } else {
            count += (higher + 1) * pos;
        }
        pos *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    try {
        if (n <= 0) {
            return false;
        }
        // A positive number is a power of two if it has exactly one bit set.
        return (n & (n - 1)) == 0;
    } catch (Exception e) {
        // In case any unexpected runtime issue occurs, treat the result as false.
        return false;
    }
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("num must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

