public static String addThousandSeparator(int n) {
    // Handle the zero case directly
    if (n == 0) {
        return "0";
    }

    // Work with the absolute value to simplify digit separation
    int absVal = Math.abs(n);
    String absStr = Integer.toString(absVal);
    StringBuilder sb = new StringBuilder(absStr);
    int length = sb.length();

    // Insert dots every three digits from the right
    int insertPos = length - 3;
    while (insertPos > 0) {
        sb.insert(insertPos, '.');
        insertPos -= 3;
    }

    String result = sb.toString();

    // Restore the negative sign if original number was negative
    if (n < 0) {
        result = "-" + result;
    }

    return result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) {
        return 0;
    }
    // Precompute adjacency matrix where can[i][j] is true if A[i] + A[j] is a perfect square
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int r = (int) Math.sqrt(sum);
            if (r * r == sum) {
                can[i][j] = true;
            }
        }
    }
    int fullMask = (1 << n) - 1;
    long[][] dp = new long[1 << n][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            long cur = dp[mask][last];
            if (cur == 0) continue;
            for (int nxt = 0; nxt < n; nxt++) {
                if ((mask & (1 << nxt)) != 0) continue;
                if (can[last][nxt]) {
                    dp[mask | (1 << nxt)][nxt] += cur;
                }
            }
        }
    }
    long result = 0;
    for (int i = 0; i < n; i++) {
        result += dp[fullMask][i];
    }
    return (int) result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    try {
        long maxArea = 0;
        java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
        for (int i = 0; i <= heights.length; i++) {
            long currentHeight = (i == heights.length) ? 0 : heights[i];
            while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
                int topIndex = stack.pop();
                long height = heights[topIndex];
                int width = stack.isEmpty() ? i : i - stack.peek() - 1;
                long area = height * width;
                if (area > maxArea) {
                    maxArea = area;
                }
            }
            stack.push(i);
        }
        return (int) maxArea;
    } catch (Exception e) {
        // In case of any unexpected runtime issue, return 0
        return 0;
    }
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum < m + n - 1; sum++) {
        if ((sum & 1) == 0) {
            int i = Math.min(sum, m - 1);
            int j = sum - i;
            while (i >= 0 && j < n) {
                result[idx++] = mat[i][j];
                i--;
                j++;
            }
        } else {
            int j = Math.min(sum, n - 1);
            int i = sum - j;
            while (j >= 0 && i < m) {
                result[idx++] = mat[i][j];
                i++;
                j--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no higher permutation
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // reverse the suffix starting at i+1
    int left = i + 1;
    int right = digits.length - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }
}

public static boolean isBoomerang(int[][] points) {
    try {
        if (points == null || points.length != 3) {
            return false;
        }
        for (int i = 0; i < 3; i++) {
            if (points[i] == null || points[i].length != 2) {
                return false;
            }
        }
        int x0 = points[0][0], y0 = points[0][1];
        int x1 = points[1][0], y1 = points[1][1];
        int x2 = points[2][0], y2 = points[2][1];
        long area2 = (long) (x1 - x0) * (y2 - y0) - (long) (x2 - x0) * (y1 - y0);
        return area2 != 0;
    } catch (Exception e) {
        return false;
    }
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    long[] ugly = new long[n];
    ugly[0] = 1L;
    int idx2 = 0, idx3 = 0, idx5 = 0;
    long next2 = 2L, next3 = 3L, next5 = 5L;
    for (int i = 1; i < n; i++) {
        long next = Math.min(next2, Math.min(next3, next5));
        ugly[i] = next;
        if (next == next2) {
            idx2++;
            next2 = ugly[idx2] * 2L;
        }
        if (next == next3) {
            idx3++;
            next3 = ugly[idx3] * 3L;
        }
        if (next == next5) {
            idx5++;
            next5 = ugly[idx5] * 5L;
        }
    }
    long result = ugly[n - 1];
    if (result > Integer.MAX_VALUE) {
        throw new ArithmeticException("The nth ugly number exceeds the range of int");
    }
    return (int) result;
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 0;
    int currentLen = 0;
    char prevChar = s.charAt(0);
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == prevChar) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            prevChar = c;
            currentLen = 1;
        }
    }
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

