public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(n);
    if (n <= 0) {
        return result;
    }
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        if (current <= n / 10) {
            current *= 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input n must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    try {
        int[] dp = new int[n + 1];
        dp[0] = 0;
        for (int i = 1; i <= n; i++) {
            int min = Integer.MAX_VALUE;
            for (int j = 1; j * j <= i; j++) {
                int candidate = dp[i - j * j] + 1;
                if (candidate < min) {
                    min = candidate;
                }
            }
            dp[i] = min;
        }
        return dp[n];
    } catch (Exception e) {
        throw new RuntimeException("Error computing min perfect square sum", e);
    }
}

public static String reverseWords(String s) {
    // Handle null input gracefully
    if (s == null) {
        return null;
    }
    // Split on space, keeping empty tokens to preserve original spacing
    String[] words = s.split(" ", -1);
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        // Reverse characters of the current word
        result.append(new StringBuilder(word).reverse());
        // Append a space after each word except the last one
        if (i < words.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}
